'use strict';
// Original interaction choreography: sleeping sky → letters → emotion stars → context.
const canvas=$('sky'),ctx=canvas.getContext('2d');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
let paused=reduced.matches,w=innerWidth,h=innerHeight,raf=0,previous=0,stars=[],dust=[],letters=[],shooters=[],gatherStart=0,revealTimer=0,finishTimer=0;
let pointer={x:-1000,y:-1000},scene='sleeping',currentTint='#a9b6ed',flare=0,nextMeteor=performance.now()+3200;
const sprites=new Map();
function sprite(color){if(sprites.has(color))return sprites.get(color);const c=document.createElement('canvas');c.width=c.height=64;const g=c.getContext('2d'),r=g.createRadialGradient(32,32,0,32,32,32);r.addColorStop(0,'#fff9e9');r.addColorStop(.045,'#fff9e9');r.addColorStop(.12,color+'dd');r.addColorStop(.3,color+'35');r.addColorStop(1,color+'00');g.fillStyle=r;g.fillRect(0,0,64,64);sprites.set(color,c);return c;}
function setScene(s){scene=s;document.body.dataset.scene=s;}
function size(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);let seed=44017;const rand=()=>{seed=seed*16807%2147483647;return seed/2147483647;};stars=Array.from({length:Math.min(1000,Math.max(220,Math.floor(w*h/1450)))},()=>({x:rand()*w,y:rand()*h,z:.15+rand()*.85,r:.2+rand()*1.2,phase:rand()*7,glow:0}));if(scene==='gathering')makeLetters();paint(performance.now(),0);}
function makeLetters(){const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');const font=getComputedStyle(document.querySelector('.feeling-line label'));g.font=`400 ${font.fontSize} ${font.fontFamily}`;g.textAlign='center';g.textBaseline='middle';g.fillStyle='white';g.fillText('Today I’m feeling …',w*.5,h*.5-12);const pixels=g.getImageData(0,0,w,h).data,points=[];for(let y=Math.max(0,Math.floor(h*.5-65));y<Math.min(h,h*.5+65);y+=3){for(let x=0;x<w;x+=3){if(pixels[(y*w+x)*4+3]>70)points.push({x,y});}}letters=points.filter((_,i)=>i%Math.max(1,Math.ceil(points.length/1400))===0).map(p=>{const a=Math.random()*Math.PI*2,r=Math.max(w,h)*(.25+Math.random()*.45);return {tx:p.x,ty:p.y,x:w*.5+Math.cos(a)*r,y:h*.5+Math.sin(a)*r,sx:w*.5+Math.cos(a)*r,sy:h*.5+Math.sin(a)*r,delay:Math.random()*.16,r:1+Math.random()};});}
function reveal(){clearTimeout(revealTimer);$('main').inert=false;$('wakeSky').hidden=true;setScene('prompt');}
function wake(instant=false){if(scene!=='sleeping')return;if(instant||paused){reveal();paint(performance.now(),0);return;}setScene('gathering');gatherStart=performance.now();makeLetters();revealTimer=setTimeout(reveal,2350);finishTimer=setTimeout(()=>letters=[],3250);}
function burst(x,y,color){if(paused)return;currentTint=color;flare=1;for(let i=0;i<95;i++){const a=Math.random()*Math.PI*2,speed=.5+Math.random()*3;dust.push({x,y,px:x,py:y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed*.65,color,life:1,decay:.005+Math.random()*.009});}if(dust.length>450)dust.splice(0,dust.length-450);}
function move(e){const old=pointer;pointer={x:e.clientX,y:e.clientY};wake();if(paused||document.querySelector('dialog[open]'))return;const dx=pointer.x-old.x,dy=pointer.y-old.y;if(Math.hypot(dx,dy)>1&&Math.hypot(dx,dy)<500){for(let i=0;i<3;i++)dust.push({x:pointer.x+(Math.random()-.5)*12,y:pointer.y+(Math.random()-.5)*12,px:old.x,py:old.y,vx:-dx*.015+(Math.random()-.5)*.4,vy:-dy*.015-.25,color:selected?.color||'#e4d7b1',life:.8,decay:.014});}if(dust.length>450)dust.splice(0,dust.length-450);}
function paint(now,dt){ctx.clearRect(0,0,w,h);ctx.globalCompositeOperation='source-over';const breath=paused?0:Math.sin(now*.00015)*.015;const clouds=[{x:.24,y:.37,rx:.52,ry:.2,c:'#263c69'},{x:.68,y:.55,rx:.49,ry:.28,c:'#302345'},{x:.52,y:.7,rx:.6,ry:.18,c:currentTint}];for(const cloud of clouds){ctx.save();ctx.translate(w*(cloud.x+breath),h*cloud.y);ctx.scale(w*cloud.rx,h*cloud.ry);const g=ctx.createRadialGradient(0,0,0,0,0,1);g.addColorStop(0,cloud.c+(cloud===clouds[2]?'0b':'35'));g.addColorStop(.45,cloud.c+'12');g.addColorStop(1,cloud.c+'00');ctx.fillStyle=g;ctx.fillRect(-1,-1,2,2);ctx.restore();}
 ctx.globalCompositeOperation='lighter';
 for(const s of stars){const ox=paused?0:(pointer.x<0?0:(pointer.x-w/2)*s.z*.006),oy=paused?0:(pointer.y<0?0:(pointer.y-h/2)*s.z*.006),x=s.x+ox,y=s.y+oy;const distance=Math.hypot(x-pointer.x,y-pointer.y);s.glow+=(Math.max(0,1-distance/130)-s.glow)*Math.min(1,dt*.008);const tw=paused?.7:.48+.22*Math.sin(now*.001*s.z+s.phase);let alpha=.18+s.z*tw+s.glow*.7;ctx.globalAlpha=Math.min(1,alpha);if(s.z>.88||s.glow>.1){const radius=s.r*(5+s.glow*15);ctx.drawImage(sprite(s.glow>.2?'#e2cc9b':'#98b4ea'),x-radius,y-radius,radius*2,radius*2);if(s.z>.98){ctx.strokeStyle='#cbdafa';ctx.lineWidth=.45;ctx.beginPath();ctx.moveTo(x-s.r*4,y);ctx.lineTo(x+s.r*4,y);ctx.moveTo(x,y-s.r*5);ctx.lineTo(x,y+s.r*5);ctx.stroke();}}else{ctx.fillStyle='#c6d4f4';ctx.beginPath();ctx.arc(x,y,s.r*.65,0,Math.PI*2);ctx.fill();}}
 const elapsed=now-gatherStart;
 if(letters.length&&gatherStart){const progress=Math.min(1,Math.max(0,(elapsed-250)/1700)),ease=1-Math.pow(1-progress,3);for(const p of letters){const t=Math.max(0,Math.min(1,(ease-p.delay)/(1-p.delay))),turn=Math.sin(t*Math.PI)*.45;const sx=p.sx-w/2,sy=p.sy-h/2;const rotX=sx*Math.cos(turn)-sy*Math.sin(turn)+w/2,rotY=sx*Math.sin(turn)+sy*Math.cos(turn)+h/2;p.x=rotX+(p.tx-rotX)*t;p.y=rotY+(p.ty-rotY)*t;ctx.globalAlpha=(.35+t*.65)*Math.min(1,elapsed/350)*Math.max(0,1-(elapsed-2050)/700);ctx.fillStyle='#ece3cf';ctx.beginPath();ctx.arc(p.x,p.y,p.r*.65,0,Math.PI*2);ctx.fill();if(t<.95){ctx.globalAlpha*=.08;ctx.strokeStyle='#a9badf';ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+(p.tx-p.x)*.04,p.y+(p.ty-p.y)*.04);ctx.stroke();}}}
 for(const p of dust){ctx.globalAlpha=Math.max(0,p.life)*.65;ctx.strokeStyle=p.color;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(p.px,p.py);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.drawImage(sprite(p.color),p.x-7,p.y-7,14,14);if(dt){p.px=p.x;p.py=p.y;p.x+=p.vx*dt*.06;p.y+=p.vy*dt*.06;p.life-=p.decay*dt*.06;}}dust=dust.filter(p=>p.life>0);
 if(!paused&&now>nextMeteor){shooters.push({x:w*(.25+Math.random()*.6),y:h*Math.random()*.4,life:1});nextMeteor=now+6500+Math.random()*7000;}for(const p of shooters){ctx.globalAlpha=Math.sin(p.life*Math.PI)*.5;const g=ctx.createLinearGradient(p.x-90,p.y-30,p.x,p.y);g.addColorStop(0,'#adbadf00');g.addColorStop(1,'#d8e3f2');ctx.strokeStyle=g;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-90,p.y-30);ctx.lineTo(p.x,p.y);ctx.stroke();p.x+=dt*.35;p.y+=dt*.115;p.life-=dt*.00065;}shooters=shooters.filter(p=>p.life>0);
 if(flare>0){ctx.globalAlpha=flare*.14;const g=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)*.65);g.addColorStop(0,currentTint);g.addColorStop(1,currentTint+'00');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);flare=Math.max(0,flare-dt*.0004);}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';}
function animate(now){const dt=Math.min(40,previous?now-previous:16);previous=now;paint(now,dt);if(!paused&&!document.hidden)raf=requestAnimationFrame(animate);}
function syncMotion(){cancelAnimationFrame(raf);previous=0;$('motionButton').setAttribute('aria-pressed',String(paused));$('motionButton').textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';if(paused&&scene==='gathering'){letters=[];reveal();}paint(performance.now(),0);if(!paused&&!document.hidden)raf=requestAnimationFrame(animate);}
document.addEventListener('pointermove',move,{passive:true});$('wakeSky').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY};wake();});$('wakeSky').onclick=()=>wake();
document.addEventListener('keydown',e=>{if(scene==='sleeping'&&(e.key==='Tab'||e.key==='Enter'||e.key===' ')){e.preventDefault();wake(true);input.focus();}});
document.querySelector('.feeling-line').addEventListener('click',e=>{if(e.target!==input){input.focus();openPicker();}});
const observer=new MutationObserver(()=>{if(scene==='sleeping'||scene==='gathering')return;const next=!$('contextStep').hidden?'context':!picker.hidden?'choosing':'prompt';if(next!==scene){setScene(next);if(next==='choosing')burst(w/2,h*.46,'#c5b9ec');}options.querySelectorAll('li').forEach((li,i)=>li.style.setProperty('--i',i));});observer.observe(picker,{attributes:true,attributeFilter:['hidden']});observer.observe($('contextStep'),{attributes:true,attributeFilter:['hidden']});observer.observe(options,{childList:true});
$('motionButton').onclick=()=>{paused=!paused;syncMotion();};reduced.addEventListener('change',e=>{paused=e.matches;syncMotion();});document.addEventListener('visibilitychange',syncMotion);window.addEventListener('resize',size);size();syncMotion();
// Reduced-motion users receive the same functional flow without a forced animation.
